"""Batch 5 (EP21-EP25) editorial content. Executed inside epdata.py, so EPS and WP come from there."""
RD5 = "Dibaca 8 Nov 2026"


def _b(rows):
    return {f"s{i+1}": r for i, r in enumerate(rows)}


def _ep(**k):
    k.setdefault("alts", [])
    return k


